import type { Player } from './index';

export const squad: Player[] = [
  // Porteros
  { number: 1, name: 'Ronwen Williams', position: 'GK', age: 34, club: 'Mamelodi Sundowns', captain: true, bio: {"es":"Williams hizo su debut internacional absoluto contra Brasil, cinco veces campeón del mundo, en marzo de 2014. Fue un bautismo de goles, ya que Williams, suplente del lesionado portero sudafricano Itumeleng Khune, recibió una paliza de 5-0. Pero el jugador del Mamelodi Sundowns no se inmutó: \"Perder 5-0 es mucho, pero estábamos jugando contra el mejor equipo del mundo. No estoy impresionado. Es una de esas cosas en el fútbol\". Ha pasado más de una década desde esa difícil presentación, y Williams ha crecido hasta convertirse en uno de los jugadores más importantes de Sudáfrica, incluso recibiendo la capitanía. En la Copa Africana de Naciones de 2023 hizo historia al convertirse en el primer portero en salvar cuatro penaltis en una única tanda de penaltis de Afcon, frente a Cabo Verde. Mientras se preparaba para afrontar cada penalización se le podía ver hablando solo y mirando al cielo como si estuviera recibiendo un consejo de alguien. Fue su hermano Marvin, quien murió en un accidente automovilístico cuando Williams tenía 18 años. \"A veces le pido que tome el control y me muestre qué camino tomar. Es como mi ángel de la guarda\".","en":"Williams made his senior international debut against the five-time World Champions Brazil in March 2014. It was a baptism of goals as Williams, deputising for the injured South African goalkeeping great Itumeleng Khune, was on the receiving end of a 5-0 drubbing. But the Mamelodi Sundowns man was unperturbed: “Losing 5-0 is a lot, but we were playing against the best team in the world. I’m not shaken. It is one of those things in soccer.” It’s been over a decade since that tough introduction, and Williams has grown to become one of the most important players for South Africa, including being given the captaincy. At the 2023 Africa Cup of Nations he made history by becoming the first keeper to save four penalties in a single Afcon penalty shootout, versus Cape Verde. As he prepared to face each penalty he could be seen talking to himself and looking up at the sky as if he was getting advice from someone. It was his brother Marvin, who died in a car crash when Williams was 18. “Sometimes I ask him to take control and show me which way to go. He’s like my guardian angel.”"}, special: "No1 goalkeeper" },
  { number: 16, name: 'Sipho Chaine', position: 'GK', age: 29, club: 'Orlando Pirates', bio: {"es":"El número uno de los Orlando Pirates es el actual portero de la temporada en la Premiership sudafricana. Su parada, sus reflejos y su comodidad con el balón en los pies le han convertido en uno de los jugadores clave de su club, y también es imprescindible en esta selección como gran suplente de Williams, admirado por el equipo técnico de los Bafana Bafana por sus cualidades de liderazgo, dentro y fuera del campo. Antes de su paso a los Piratas en 2022, se hizo un nombre jugando en el Bloemfontein Celtic, un club lleno de historia pero que tuvo que vender su estatus de máxima categoría en 2021 debido a presiones financieras. Desde que se mudó a Orlando, ha ayudado a los Piratas a ganar siete trofeos al momento de escribir este artículo y se merecía plenamente su lugar en el equipo de este verano.","en":"Orlando Pirates’ No1 is the reigning goalkeeper of the season in the South African Premiership. His shot-stopping, reflexes and comfort with the ball at his feet have seen him become one of the key players for his club, and he is essential to this national squad too as a great deputy to Williams, admired by the Bafana Bafana technical team for his leadership qualities, on and off the field. Before his switch to Pirates in 2022 he made his name while playing for Bloemfontein Celtic, a club steeped in history but which had to sell its top-flight status in 2021 due to financial pressures. Since moving to Orlando he has helped Pirates win seven trophies at the time of writing, and fully deserved his spot in this summer’s squad."} },
  { number: 22, name: 'Ricardo Goss', position: 'GK', age: 32, club: 'Siwelele FC', bio: {"es":"“The Goose” trae buenas vibraciones dentro del equipo sudafricano, y a menudo se le ve liderando el canto de los Bafana Bafana antes y después de los partidos. Goss fue criado por su madre soltera, Faith, quien trabajaba como enfermera en Durban y se aseguraba de que su hijo nunca sintiera el vacío de no tener un padre presente. A medida que crecía, Ricardo soñaba con convertirse en futbolista, inspirado por el ex portero de los Bafana Bafana Brian “Spiderman” Baloyi y, después de comenzar en Lamontville Golden Arrows, se abrió camino hasta la cima. Goss, un gran comunicador, habla con fluidez varios de los 12 idiomas oficiales de Sudáfrica, incluidos IsiZulu, IsiXhosa e inglés. Realizó una brillante actuación individual con el Siwelele FC en marzo contra los Orlando Pirates, lo que llevó al entrenador de los Piratas, Abdeslam Ouaddou, a decir: \"Tenemos que darle crédito a su portero. Hoy tuvieron a Jesucristo en la portería\".","en":"“The Goose” brings the good vibes within the South African squad, often seen leading Bafana Bafana’s singing before and after matches. Goss was raised by his single mother, Faith, who worked as a nurse in Durban while ensuring her son never felt the void of not having a present father. As he grew, Ricardo dreamt about becoming a footballer, inspired by the former Bafana Bafana goalkeeper Brian “Spiderman” Baloyi, and, after starting out at Lamontville Golden Arrows, he worked his way to the top. A great communicator, Goss is fluent in several of South Africa’s 12 official languages, including IsiZulu, IsiXhosa and English. He produced a brilliant individual display for Siwelele FC in March against Orlando Pirates, prompting the Pirates manager, Abdeslam Ouaddou, to say: “We have to give credit to their goalkeeper. They had Jesus Christ in the goal today.”"} },
  // Defensores
  { number: 2, name: 'Thabang Matuludi', position: 'DF', age: 22, club: 'Polokwane City', bio: {"es":"Con 1,88 m, Matuludi no es el típico lateral. Además de poseer mucha resistencia en el flanco derecho, tiene presencia física real y es dominante en el aire. Y este podría ser un verano transformador para él: llegó a la Copa del Mundo contratado por el Polokwane City de la Premiership sudafricana, pero cualquier momento de juego en el torneo podría mejorar su perfil y atraer el interés de clubes más grandes. Al igual que su competencia directa en el lateral derecho, Khuliso Mudau, puede producir un juego de pies sedoso en los momentos adecuados. El entrenador de su club, Phuti Mohafe, defendió su caso para un lugar en el equipo de Hugo Broos, diciendo en marzo: \"El chico es humilde y está trabajando duro. Y sigo repitiendo que, según mi percepción, es el segundo mejor lateral derecho [del país]. Lo está haciendo bien y su comportamiento es excelente y le agradezco que esté tan concentrado\".","en":"At 1.88m, Matuludi is not your typical full-back. As well as possessing stacks of stamina on the right flank he has real physical presence and is aerially dominant. And this could be a transformative summer for him: he arrived at the World Cup contracted to South African Premiership side Polokwane City, but any game time at the tournament could boost his profile and attract interest from bigger clubs. Just like his direct competition at right-back, Khuliso Mudau, he can produce some silky footwork in the right moments. His club coach, Phuti Mohafe, championed his case for a place in Hugo Broos’s squad, saying in March: “The boy is humble and the boy is working hard. And I’m still saying again that according to my perception he is the second-best right-back [in the country]. He’s doing well and his behaviour is tops and I thank him for being this focused.”"} },
  { number: 3, name: 'Khulumani Ndamane', position: 'DF', age: 22, club: 'Mamelodi Sundowns', bio: {"es":"Uno de los defensores más interesantes del fútbol sudafricano en este momento. Partidario de los Kaizer Chiefs desde su infancia, vivió su sueño al unirse al sistema juvenil del club de Soweto, pero la falta de oportunidades en el primer equipo lo llevó a cambiarse al TS Galaxy para la temporada 2024-25. \"En equipos como los Chiefs, las expectativas son enormes\", dijo. \"Cuando eres joven, cometes errores. Pero en el Galaxy te permitieron cometer errores y crecer. Te ayuda mentalmente y como jugador\". Esas lecciones dieron sus frutos: ahora es un jugador clave para los campeones en serie Mamelodi Sundowns, y una gran opción en la defensa para Hugo Broos este verano. Sin embargo, su carrera internacional tuvo un comienzo complicado. La primera vez que lo llamaron se alegró y luego se dio cuenta de que no tenía pasaporte. \"Las cosas sucedieron demasiado rápido\", dijo al Sunday Tribune. \"Estaba feliz de jugar en el PSL, así que la selección nacional ni siquiera estaba en mi mente. Entonces, de repente, Dios hizo que las cosas sucedieran tan rápido. Me lo perdí, pero aprendí de ese error. ¡Ahora tengo mi pasaporte! Me dije a mí mismo que si el entrenador Broos me vio una vez y le gustó lo que vio, debo seguir trabajando, vendrá otra oportunidad, y así fue\".","en":"One of the most exciting defenders in South African football at the moment. A childhood supporter of Kaizer Chiefs, he lived his dream by joining the Soweto club’s youth system, but a lack of first-team opportunities led him to switch to TS Galaxy for the 2024-25 season. “At teams such as Chiefs, expectations are huge,” he said. “As a youngster, you’ll make mistakes. But at Galaxy, they allowed you to make mistakes and grow. It helps you mentally and as a player.” Those lessons paid off: he is now a key player for serial champions Mamelodi Sundowns, and a great option at the back for Hugo Broos this summer. His international career had a tricky start, though. The first time he was called up, he was delighted, then realised he didn’t have a passport. “Things happened too fast,” he told the Sunday Tribune. “I was just happy to be playing in the PSL, so the national team wasn’t even on my mind. Then suddenly, God made things happen so fast. I missed out, but I learnt from that mistake. Now I have my passport! I told myself that if coach Broos saw me once and liked what he saw, I must just keep working, another opportunity will come - and it did.”"} },
  { number: 14, name: 'Mbekezeli Mbokazi', position: 'DF', age: 23, club: 'Chicago Fire', bio: {"es":"El ascenso de Mbokazi ha sido rápido. El corpulento defensor apenas hizo su debut profesional a principios de 2025, pero rápidamente se convirtió en un jugador clave para los Orlando Pirates, capitaneando el equipo a una edad temprana, antes de ser fichado por el Chicago Fire de la MLS a principios de este año. La medida causó una tormenta cuando el entrenador de Sudáfrica, Hugo Broos, atacó la decisión, argumentando que Mbokazi debería haberse unido a un mejor club en una mejor liga en Europa. Broos atacó las motivaciones de la agente Basia Michaels – “una mujercita simpática que cree saber fútbol” – y dijo que le daría una reprimenda a Mbokazi por llegar tarde a un campo de entrenamiento de la selección nacional: \"Charlaré con él. Es un chico negro. Saldrá de mi habitación como un chico blanco. Porque eso no lo puedo aceptar. Él piensa que es una estrella. Ésta es la actitud de una estrella: 'Yo decidiré cuando venga'. Estoy muy enojado por su actitud\". Más tarde, Broos se disculpó, diciendo que su \"elección de palabras no fue la correcta\", pero insistió en que \"nunca quiso hacer un comentario racista o sexista\" y que \"no era ni racista ni sexista\". Hicieron las paces a tiempo para este verano. Mbokazi, central zurdo, es una gran ventaja para el equipo. Conocido por su excelente ética de trabajo, se ganó con razón su apodo \"TLB\", en referencia al vehículo agrícola todoterreno y de servicio pesado, la retroexcavadora cargadora.","en":"Mbokazi’s rise has been rapid. The bulky defender only made his professional debut in early 2025, but quickly became a key player for Orlando Pirates, captaining the side at a young age, before being signed by MLS side Chicago Fire at the start of this year. The move caused a storm as South Africa coach Hugo Broos attacked the decision, arguing Mbokazi should have joined a better club in a better league in Europe. Broos attacked the motivations of agent Basia Michaels – “a nice little woman who thinks she knows football” – and said he would give Mbokazi a dressing down for arriving late to a national team training camp: “I will have a chat with him. He is a black guy. He will get out of my room as a white guy. Because that I can’t accept. He thinks he is a star. This is the attitude of a star: ‘I will decide when I come.’ I’m very angry about his attitude.” Broos later apologised, saying his “choice of words was not the right one\", but insisted he \"never wanted to make a racist or sexist comment\" and was \"neither a racist nor a sexist\". They made peace in time for this summer. Mbokazi, a left-footed centre-back, is a huge asset to the squad. Known for his terrific work ethic, he properly earned his nickname “TLB”, in reference to the heavy-duty, all-round agricultural vehicle, the tractor loader backhoe."}, special: "Rapid riser" },
  { number: 18, name: 'Samukele Kabini', position: 'DF', age: 20, club: 'Molde', bio: {"es":"En los últimos años, Sudáfrica ha tenido dificultades para exportar jugadores a Europa; la época en la que estrellas como Benni McCarthy, Steven Pienaar y Aaron Mokoena representaban al país en las ligas más emocionantes de Europa parece haber quedado hace mucho tiempo. Pero, en un equipo sudafricano compuesto principalmente por jugadores locales, Kabini es una de las excepciones. El lateral izquierdo juega en el Molde, al que llegó el año pasado procedente del TS Galaxy, convirtiéndose en el primer jugador sudafricano del club noruego de primera categoría. Tuvo que adaptarse rápidamente a las diferentes condiciones y dijo: \"Aquí hace mucho frío, nieva y, a veces, en los entrenamientos tienes tanto frío que ni siquiera puedes patear la pelota, los dedos de los pies están tan congelados dentro de las botas. Prefiero el sol a la nieve\". Aunque su posición preferida es la de lateral izquierdo, su altura le permite también hacer un trabajo en el centro, una gran versatilidad para un equipo mundialista.","en":"In recent years South Africa has struggled to export players to Europe – the era when stars such as Benni McCarthy, Steven Pienaar and Aaron Mokoena were representing the country in Europe’s most exciting leagues feels a long time ago. But, in a South African squad consisting largely of locally based players, Kabini is one of the exceptions. The left-back plays his football for Molde, whom he joined last year from TS Galaxy, becoming the Norwegian top-flight club’s first ever South African player. He had to adapt fast to the different conditions, saying: “It’s very cold here, it snows, and sometimes in training you are so cold you can’t even kick the ball, your toes are so frozen inside your boots. I prefer the sun to the snow.” Although his preferred position is left-back, his height means he can also do a job in the centre – great versatility for a World Cup squad."} },
  { number: 19, name: 'Nkosinathi Sibisi', position: 'DF', age: 30, club: 'Orlando Pirates', bio: {"es":"Un gran líder y señor confiable para el club y el país. Sibisi nunca se enfurruña cuando no está jugando y lo da todo cuando lo está. Hizo su debut con los Bafana Bafana durante el primer partido de Hugo Broos como entrenador de la selección nacional, y Broos dijo: \"Siempre puedes contar con él. En el grupo, los jugadores más jóvenes lo respetan. No es un bocazas, pero es muy importante para el ambiente del grupo\". Hablando antes de que se confirmara su lugar en el equipo de este verano, Sibisi dijo que acogía con agrado la competencia por los puestos de central. \"El hierro se afila con el hierro. Creo que habla de la calidad que tenemos no sólo en la posición de defensa central, sino en todo el campo. Creo que ya sea que juegue yo u otros muchachos, no se nota la diferencia y creo que así es como debe ser. [La competencia] simplemente ayuda a fortalecer a nuestro equipo\".","en":"A great leader and Mr Reliable for club and country. Sibisi never sulks when he is not playing and gives his all when he is. He made his debut for Bafana Bafana during Hugo Broos’s first match as the national team coach, with Broos saying: “You can always count on him. They have respect for him in the group, the younger players. He’s not a big mouth, but he’s very important for the atmosphere in the group.” Speaking before his place in this summer’s squad was confirmed, Sibisi said he welcomed the competition for places at centre-back. “Iron sharpens iron. I think it speaks to the quality we have not only in the central defence position, but everywhere around the pitch. I think whether it's me playing or other guys playing, you couldn't tell the difference and I think that's how it should be. [The competition] just helps strengthen our team.”"} },
  { number: 20, name: 'Khuliso Mudau', position: 'DF', age: 31, club: 'Mamelodi Sundowns', bio: {"es":"Una parte clave de los planes del técnico Hugo Broos de cara a este torneo. El merodeador lateral derecho es un líder inspirador para el club y el país, y aporta una enorme energía y versatilidad. Cuando no está haciendo tacleadas hábiles en su propio campo, está atacando a los defensores rivales, navegando arriba y abajo por el flanco derecho, ganándose su apodo de \"Marinero\". Broos inicialmente dudaba de las cualidades defensivas de Mudau, pero ahora habla muy bien del lateral. \"Ahora no sólo es un lateral derecho fuerte ofensivamente, sino que ha aprendido mucho a la defensiva\", dijo Broos. \"Khuliso es el mejor lateral derecho de este país y uno de los mejores laterales derechos de África\". Este año fue galardonado con el premio al Futbolista Destacado del Año en los Premios Icons of Africa porque \"encarna lo que significa ser un futbolista africano moderno: resiliente, trabajador y comprometido con la excelencia tanto dentro como fuera del campo. Su viaje desde Limpopo hasta la cima del fútbol sudafricano continúa inspirando a jóvenes atletas de todo el continente\".","en":"A key part of coach Hugo Broos’s plans coming into this tournament. The marauding right-back is an inspirational leader for club and country, and brings huge energy and versatility. When he is not making slick tackles in his own half, he is nutmegging opposition defenders, sailing up and down the right flank, earning his “Sailor” nickname. Broos initially doubted Mudau’s defensive qualities, but he now speaks highly of the full-back. “Now he is not only a right back who is offensively strong, he has learned a lot defensively,” Broos said. “Khuliso is the best right-back in this country, and one of the best right-backs in Africa.” He was awarded Outstanding Footballer of the Year at the Icons of Africa Awards this year, because “he embodies what it means to be a modern African footballer: resilient, hardworking, and committed to excellence both on and off the field. His journey from Limpopo to the top of South African football continues to inspire young athletes across the continent.”"}, special: "Natural leader" },
  { number: 21, name: 'Ime Okon', position: 'DF', age: 22, club: 'Hannover 96', bio: {"es":"Gavin Hunt, entrenador de Okon en el ahora desaparecido SuperSport United, describió al joven defensor en 2023 como un jugador con un enorme potencial, diciendo: \"Lo encontramos en Randburg el año pasado, es increíble. Tiene buenos atributos... encontrará su camino\". Nacido en Sudáfrica de padre nigeriano y madre sudafricana, las cualidades de Okon incluyen fuerza aérea en ambos box y compostura bajo presión, y ha demostrado su calidad en Alemania con el Hannover 96 de segunda división, al que se unió el año pasado. Su progreso internacional se ha visto obstaculizado por una lesión y trabajó duro para volver a la configuración y asegurar su lugar para este verano. “Aquí es donde siempre quise estar”, dijo después de su convocatoria en marzo. \"Desde mi adolescencia he estado trabajando duro. Creo que todo encaja una vez que sigues trabajando duro y sigues creyendo que vas a terminar logrando lo que quieres lograr. Esa es simplemente mi opinión sobre todo\". Su hermano menor, Udeme, es un velocista de clase mundial que ganó el oro en los 400 metros en el Campeonato Mundial de Atletismo Sub-20 de 2024 y formó parte del equipo que ganó el oro en los Relevos Mundiales de Atletismo de 2025 en China.","en":"Gavin Hunt, Okon’s coach at the now defunct SuperSport United, described the young defender in 2023 as a player with huge potential, saying: “We found him at Randburg last year, he’s amazing. He’s got good attributes … he will find his path.” Born in South Africa to a Nigerian father and a South African mother, Okon’s qualities include aerial strength in both boxes and composure under pressure, and he has gone on to prove his quality in Germany with second-tier Hannover 96, whom he joined last year. His international progress has been hampered by injury, and he worked hard to return to the set-up and secure his spot for this summer. “This is where I’ve always wanted to be,” he said after his call-up in March. “Since my adolescent years I’ve been working hard. I think everything just falls in place once you just keep on working hard and you keep believing that you are going to end up achieving what you want to achieve. That’s just my view on everything.” His younger brother Udeme is a world-class sprinter who won gold in the 400m at the 2024 World Athletics Under-20 Championships, and was part of the team that won gold at the 2025 World Athletics Relays in China."} },
  { number: 24, name: 'Olwethu Makhanya', position: 'DF', age: 22, club: 'Philadelphia Union', bio: {"es":"Al igual que su compañero de equipo Jayden Adams, Makhanya es producto de la academia Stellenbosch. Después de algunas actuaciones emocionantes para el club con sede en Western Cape, incluida la obtención del galardón de Jugador Más Prometedor en Stellies durante la temporada 2022-23, Makhanya se mudó a Filadelfia. Esto fue en 2023, cuando el joven defensor formó parte de la iniciativa Sub-22 de la Major Soccer League, en la que recientemente su compatriota Mbekezeli Mbokazi también se mudó a Estados Unidos. En 2025, Makhanya ayudó a anclar una línea defensiva que concedió 35 goles, el mínimo de la liga. Ahora en su cuarta temporada con el club estadounidense, Makhanya ha sido recompensado con un lugar en la Copa del Mundo y la oportunidad de ganar su primera internacionalización absoluta con su país en Norteamérica. “Significa mucho para mí”, dijo Makhanya al Union Soccer Blog. \"Es una oportunidad por la que he estado trabajando duro. Está justo frente a mí ahora. Es una oportunidad para mí de ir allí y mostrarme\".","en":"Like teammate Jayden Adams, Makhanya is a product of the Stellenbosch academy. After some exciting performances for the Western Cape-based club, including earning the accolade of Most Promising Player at Stellies during the 2022-23 season, Makhanya moved to Philadelphia. This was in 2023, with the young defender forming part of the Major Soccer League side’s Under-22 initiative, which recently saw compatriot Mbekezeli Mbokazi also make the switch to the US. In 2025, Makhanya helped anchor a backline that conceded a league-low 35 goals. Now in his fourth season with the US club, Makhanya has been rewarded with a World Cup spot and an opportunity to earn his first international senior cap for his country in North America. “It means a lot to me,” Makhanya told Union Soccer Blog. “It’s an opportunity that I’ve been working hard for. It’s right in front of me now. It’s an opportunity for me to go there and showcase myself.”"}, special: "Newcomer" },
  { number: 25, name: 'Kamogelo Sebelebele', position: 'DF', age: 23, club: 'Orlando Pirates', bio: {"es":"Sebelebele mantiene la cabeza gacha y hace su trabajo con diligencia. Con una presencia explosiva y eléctrica en el flanco derecho, el jugador de 23 años ha sido un jugador clave para los Piratas desde que llegó al equipo de Soweto procedente del TS Galaxy hace un año. \"En TS Galaxy, siempre aplicamos la razón a estos asuntos. Ahora somos conocidos por ser un club que brinda oportunidades a los jugadores, y cuando hacemos estas transferencias, analizamos una serie de variaciones\", dijo el presidente del Galaxy, Tim Sukazi, a SABC cuando Sebelebele dejó el club por los Piratas en 2025. \"Por ejemplo, un Kamogelo Sebelebele, que es una transferencia no necesariamente en beneficio de TS Galaxy, sino en beneficio del fútbol en Sudáfrica, que también consideramos como TS Galaxy Somos un club muy consciente y agradecido de su papel dentro del fútbol del país”. Este enfoque prospectivo del equipo de Mpumalanga ha funcionado, con la inclusión de Sebelebele en la Copa Mundial.","en":"Sebelebele keeps his head down and does his job diligently. An explosive and electric presence on the right flank, the 23-year-old has been a key player for Pirates since joining the Soweto side from TS Galaxy a year ago. “At TS Galaxy, we always apply reason to these matters. We are known now to be a club that affords opportunity to players, and when we do these transfers, we look at a number of variances,” Galaxy chairperson Tim Sukazi told SABC when Sebelebele left the club for Pirates in 2025. “For example, a Kamogelo Sebelebele, who is a transfer not necessarily to the benefit of TS Galaxy, but to the benefit of football in South Africa, which we also look at as TS Galaxy. We are a club that’s very aware and appreciative of its role within the game of football within the country.” This forward-looking approach by the Mpumalanga team has worked out, with Sebelebele’s World Cup inclusion."}, special: "Electric" },
  { number: 26, name: 'Bradley Cross', position: 'DF', age: 25, club: 'Kaizer Chiefs', bio: {"es":"Cross fue moldeado por las academias de Mpumalanga Black Aces y Bidvest Wits. Ambos equipos ya no existen, pero Cross aún conserva la pasión por el fútbol que le inculcaron, incluso después de sufrir un revés después de hacer un movimiento internacional de ensueño. El Schalke alemán llegó en 2018, pero el defensa tuvo problemas para anclarse, incluso después de dejar Alemania por el Newcastle United. Después de eso, optó por regresar a casa y jugó en Maritzburg United y Golden, antes de conseguir el traslado de sus sueños a los Chiefs. \"Me han convocado antes, pero aún no he podido debutar\", dijo en 2025. \"Significaría mucho para mí [representar a mi país], porque ha sido uno de mis objetivos durante mucho tiempo. Sólo necesito seguir trabajando duro, mantener la cabeza gacha y permanecer en mi carril. Sería un gran logro ser convocado\". Ahora se dirige al Mundial con su país.","en":"Cross was moulded by the academies of Mpumalanga Black Aces and Bidvest Wits. Both of those teams are now defunct, but Cross still carries the passion for soccer they instilled in him — even after suffering a setback after making a dream international move. German side Schalke came swooping in 2018 but the defender struggled to anchor himself, even after leaving Germany for Newcastle United. After that, he opted to return home and played at Maritzburg United and Golden, before earning a dream move to Chiefs. “I’ve been called up before, but I haven’t been able to make my debut yet,” he said in 2025. “It would mean so much to me [to represent my country], because it’s been one of my goals for a long time. I just need to keep working hard, keep my head down and stay in my lane. It would be a great achievement to be called up.” Now he is heading to the World Cup with his country."} },
  // Volantes
  { number: 4, name: 'Teboho Mokoena', position: 'MF', age: 29, club: 'Mamelodi Sundowns', bio: {"es":"Uno de los jugadores más importantes de Sudáfrica desde que Hugo Broos fue nombrado entrenador en mayo de 2021. “Tebza” es tan sólido como parece en el mediocampo, con pases precisos, tiros de larga distancia y un ritmo de trabajo implacable. También es un especialista en tiros libres. Al igual que el capitán Ronwen Williams, ascendió de rango en SuperSport United, antes de unirse a Sundowns. Durante la clasificación para el Mundial de 2026, estuvo en el centro de un escándalo que casi le cuesta a Sudáfrica un lugar en la fase final cuando, sin saberlo, jugó en la victoria por 2-0 sobre Lesotho a pesar de estar suspendido. La FIFA le dio a Lesotho una goleada de 3-0, multó a la FA de Sudáfrica con £9,300 y emitió una advertencia a Mokoena. Habló de ello el año pasado, contando a Radio 2000 sobre el abuso que él y su familia habían recibido: \"Sabía que [sucedería] en las redes sociales, pero cuando pasó dos veces en el centro comercial, fue cuando me golpeó fuerte. Cuando sucedió cara a cara supe que me iba a arrepentir por el resto de mi vida... Ni siquiera sabía que tenía esas tarjetas amarillas, así que fue muy difícil, y me sentí aliviado cuando nos clasificamos para la Copa del Mundo. No estaba feliz pero sí aliviado\". Fueron unos meses difíciles para mí y no estaba en casa... El entrenador dijo que no debería culparme y que todos estamos involucrados y todos deberíamos haberlo sabido”.","en":"One of South Africa’s most essential players since Hugo Broos was appointed manager in May 2021. “Tebza” is as solid as they come in midfield, with pinpoint passing, long-range shots and relentless work rate. He is also a free-kick specialist. Like captain Ronwen Williams, he came up through the ranks at SuperSport United, before joining Sundowns. During qualification for the 2026 World Cup he was at the centre of a scandal which almost cost South Africa a place in the finals when he unwittingly played in a 2-0 win over Lesotho despite being suspended. Fifa handed Lesotho a 3-0 walkover, fined South Africa’s FA £9,300 and issued Mokoena with a warning. He spoke about it last year, telling Radio 2000 about the abuse he and his family had received: “I knew [it would happen] on social media, but when it happened twice at the mall, that’s when it hit me hard. When it happened face-to-face I knew I was going to regret it for the rest of my life … I didn’t even know that I had those yellow cards, so it was very difficult, and I was relieved when we qualified for the World Cup. I was not happy but relieved. It was a tough few months for me, and I was not myself at home … The coach said I shouldn’t blame myself and that we’re all involved and we should have all known.”"}, special: "Essential" },
  { number: 5, name: 'Thalente Mbatha', position: 'MF', age: 26, club: 'Orlando Pirates', bio: {"es":"El nombre de pila de Mbatha – “talento” en el coloquial isizulu, uno de los 12 idiomas oficiales de Sudáfrica – le sienta bien. Después de impresionar con el ahora desaparecido SuperSport United, se mudó a Orlando Pirates en 2024 y consolidó su reputación como mediocampista polivalente. Tiene un tiro potente y mucha energía y velocidad. Su ex entrenador en Orlando Pirates, José Riveiro, describió a Mbatha como un “jugador de fútbol realmente completo”, mientras que el centrocampista le dio crédito al español por haberlo convertido en el jugador en el que se ha convertido: “Estoy muy agradecido al entrenador y a los Piratas por darme la oportunidad… El entrenador ha influido mucho en mi fútbol”. También habló recientemente sobre cómo jugar para un gran club había cambiado su vida, y le dijo a iDiski Times: \"Recibí mi primera convocatoria para la selección nacional, pude ser visto fuera del país y mi nombre ahora está en un escenario más grande. Eso es algo por lo que siempre he trabajado. [Aunque] ahora es difícil hacer las cosas en privado, donde puedo reírme a carcajadas en un centro comercial o ser yo mismo. Ahora hay opiniones sobre ti. La gente te observa, te juzga y, a veces, incluso te malinterpreta. Tengo un desacuerdo en una tienda o digo algo que a alguien no le gusta, de repente es un titular, debido a quién soy, eso supone mucha presión para que un jugador joven se adapte”.","en":"Mbatha’s first name – “talent” in colloquial IsiZulu, one of South Africa’s 12 official languages – suits him. After impressing with the now defunct SuperSport United he moved to Orlando Pirates in 2024 and cemented his reputation as an all-action midfielder. He packs a powerful shot and has stacks of energy and speed. His former coach at Orlando Pirates, José Riveiro, described Mbatha as a “really complete football player”, while the midfielder credited the Spaniard with making him the player he has become: “I am really grateful to the coach and Pirates for giving me the opportunity… The coach has influenced my football greatly.” He also spoke recently about how playing for a big club had changed his life, telling iDiski Times: “I got my first national team call-up, I was able to be seen outside the country, and my name is now on a bigger stage. That’s something I’ve always worked toward. [Although] it’s hard to do things in private now, where I can just laugh out loud in a mall or be myself. Now there are opinions about you. People watch you, judge you, and sometimes even misunderstand you. If I have a disagreement in a shop or say something that someone doesn’t like, suddenly it’s a headline, because of who I am. That’s a lot of pressure for a young player to adjust to.”"}, special: "All-action midfielder" },
  { number: 6, name: 'Aubrey Modiba', position: 'MF', age: 30, club: 'Mamelodi Sundowns', bio: {"es":"El “Cartero” siempre entrega. Modiba es cómodamente el mejor en su posición en Sudáfrica, y su inteligencia futbolística y aplicación técnica lo distinguen de otros laterales izquierdos. Prueba de ello es que sus asistencias desde esa posición no siempre son solo centros, sino también pases en profundidad perfectamente sincronizados que dividen la defensa. También tiene un tiro potente. Modiba es oriundo de Mentz, en la provincia de Limpopo, y regularmente regresa a la comunidad que lo formó, donando equipos como uniformes y balones de fútbol a instituciones, y dirigiendo allí su propia fundación que se enfoca en temas que van desde la seguridad alimentaria hasta la discapacidad infantil. Dice que les dice a los jóvenes allí: \"Pongan su energía en el lugar correcto. No todos están destinados a ser el próximo Aubrey Modiba, y eso está bien. Algunos están destinados al rugby, otros al mundo académico, otros al arte. El punto es encontrar su pasión y darlo todo. Sea usted mismo. Sea dueño de su camino\".","en":"The “Postman” always delivers. Modiba is comfortably the best in his position in South Africa, with his football intelligence and technical application setting him apart from other left-backs. Proof of that is that his assists from the position are not always just crosses, but perfectly-timed, defence-splitting through-balls too. He also packs a powerful shot. Modiba hails from Mentz in the province of Limpopo and regularly puts back into the community that shaped him, donating equipment such as football kits and balls to institutions, and running his own foundation there focusing on issues ranging from food security to childhood disability. He says he tells youngsters there: “Put your energy in the right place. Not everyone is meant to be the next Aubrey Modiba, and that’s OK. Some are meant for rugby, some for academics, some for art. The point is to find your passion and give it everything. Be yourself. Own your path.”"}, special: "'The Postman'" },
  { number: 13, name: 'Sphephelo Sithole', position: 'MF', age: 27, club: 'CD Tondela', bio: {"es":"Apodado “Yaya”, Sithole es un centrocampista grande, poderoso y sereno, pero a diferencia del gran marfileño Yaya Touré, es más un operador pragmático y defensivo. Su trabajo para los Bafana Bafana es sentarse profundamente y proteger la defensa. Algo inusual en este equipo internacional es que nunca jugó profesionalmente en Sudáfrica y pasó toda su carrera absoluta en Portugal, aunque antes de este torneo expresó interés en un cambio, y una buena actuación en la Copa del Mundo debería abrirle muchas opciones. \"He estado en Portugal durante ocho años, casi nueve ahora, así que ir a otro lugar, tal vez fuera de Portugal, si las cosas van bien, podría ser bueno para mi carrera. Quiero tener la oportunidad de ir a jugar a otro lugar\". Tuvo que mostrar fortaleza mental en 2024 después de fracturarse la tibia y el peroné en un partido de clasificación de la Afcon contra Sudán del Sur. \"Pensé que tal vez era el final de mi carrera\", dijo el año pasado. “Quiero agradecer a Dios por la oportunidad que me dio de volver a jugar al fútbol”.","en":"Nicknamed “Yaya”, Sithole is a big, powerful, composed midfielder – but unlike the Ivorian great Yaya Touré he is more of a pragmatic, defensive operator. His job for Bafana Bafana is to sit deep and protect the defence. Unusually in this international squad, he has never played professionally in South Africa and has spent his entire senior career in Portugal, though before this tournament he expressed an interest in a change, and a good showing at the World Cup should open up plenty of options. “I’ve been in Portugal for eight years, close to nine now, so for me to go somewhere else, maybe outside of Portugal, if things go well, could be good for my career. I want an opportunity to go and play somewhere else.” He had to show mental strength in 2024 after fracturing his tibia and fibula in an Afcon qualifier against South Sudan. “I thought maybe it was the end of my career,” he said last year. “I would like to thank God for the opportunity he gave me to play football again.”"} },
  { number: 23, name: 'Jayden Adams', position: 'MF', age: 25, club: 'Mamelodi Sundowns', bio: {"es":"Uno de los jugadores más interesantes del fútbol sudafricano en estos momentos. El centrocampista de los Sundowns tiene una gran calidad en el medio del campo, confiado y cómodo en la posesión, nunca tiene miedo de recibir el balón bajo presión. Su habilidad para pasar se destaca y se le vinculó con un gran traslado a Europa antes del torneo de este verano. Pasó por el sistema juvenil de Stellenbosch y se convirtió en el primer producto de la academia en firmar un contrato profesional. Sin embargo, su progreso a nivel internacional no ha sido del todo fluido. Cuando lo convocaron para un partido de clasificación para la Afcon de 2025, llegó tarde, lo que provocó que el entrenador Hugo Broos lo excluyera durante un año. \"Él hizo lo que hizo y yo no estaba contento\", explicó Broos en marzo. \"Pero ha aprendido mucho, y ahora lo sabe. Cuando lo ves jugar, es más maduro y las cualidades todavía están ahí. Y esta madurez es algo que obtuvo en el último año. Él mismo era consciente de ello; se miró al espejo y dijo: 'Jayden, si sigues así, tu carrera estará terminada'... Todo el mundo sabe que es un muy buen jugador y creo que puede ayudarnos mucho\".","en":"One of the most exciting players in South African football right now. The Sundowns midfielder has huge quality in the middle of the pitch, confident and comfortable in possession, never shy to receive the ball under pressure. His pinpoint passing ability shines through, and he was linked with a big move to Europe before this summer’s tournament. He came through Stellenbosch’s youth system, becoming their first academy product to sign a professional contract. His progress at international level has not been totally smooth though. When he was called up for a 2025 Afcon qualifier he arrived late, resulting in coach Hugo Broos excluding him for a year. “He did what he did, and I was not happy,” Broos explained in March. “But he’s learnt a lot, and he knows now. When you see him playing, he’s more mature, and the qualities are still there. And this maturity is something he got in the last year. He was conscious of it himself; he looked in the mirror and said, ‘Jayden, if you go on like this, your career is finished’ … Everyone knows he’s a very good player and I think he can help us a lot.”"}, special: "Going places" },
  // Delanteros
  { number: 7, name: 'Oswin Appollis', position: 'FW', age: 24, club: 'Orlando Pirates', bio: {"es":"En su mejor momento, es un placer ver a Appollis. Rápido, con un centro de gravedad bajo y buen ojo para los pases que dividen la defensa, también aporta una versatilidad útil, capaz de jugar en cualquier banda o justo detrás del delantero. A nivel juvenil fue desarrollado por la famosa Academia Ikamva de los Cape Town Spurs y representó al SuperSport United cuando era joven. Pero fue en el Polokwane City, el club sudafricano de primera categoría, donde realmente se anunció. Ha estado en los Piratas desde el año pasado y se ha vuelto indispensable tanto para el club como para el país. Lo cual es toda una historia, dado que en 2022 casi se aleja del fútbol, ​​frustrado por cómo avanzaba su carrera. Fue necesario el respetado entrenador de fútbol sudafricano Kwanele Kopo para convencerlo de volver a atarse las botas. Appollis dijo el año pasado: \"Él es quien salvó mi carrera. Estaba sentado en casa y no quería jugar, pero Kopo me llamó y nunca se dio por vencido. Luego llamó a mi madre y ella me convenció para que volviera. Hasta el día de hoy, todavía nos comunicamos y creo que si no fuera por él, no estaría donde estoy hoy\". Fuera del fútbol, ​​Appollis es un ávido jugador. Juego favorito: Call of Duty.","en":"At his best, Appollis is a joy to watch. Fast, with a low centre of gravity and an eye for defence-splitting passes, he also brings useful versatility, able to play on either wing, or just behind the striker. At youth level he was developed by Cape Town Spurs’ famous Ikamva Academy, and represented SuperSport United as a youngster. But it was with South African top-flight club Polokwane City that he truly announced himself. He has been at Pirates since last year, and has become indispensable for both club and country. Which is quite some story, given that in 2022 he almost walked away from football, frustrated with how his career was progressing. It took the respected South African football coach Kwanele Kopo to convince him to lace up his boots again. Appollis said last year: “He is the one who saved my career. I was sitting at home and didn't want to play, but Kopo called me and never gave up on me. He then called my mother, and she convinced me to go back. To this day, we still communicate with one another, and I believe that if it weren't for him, I wouldn't be where I am today.\" Outside football, Appollis is an avid gamer. Favourite game: Call of Duty."} },
  { number: 8, name: 'Tshepang Moremi', position: 'FW', age: 26, club: 'Orlando Pirates', bio: {"es":"Rápido y directo, el apodo de Moremi es “Rea Vaya”, palabra coloquial en sesotho que significa “nos vamos”. Su producto final y su consistencia general siguen siendo problemas para el jugador de 25 años, pero ha crecido hasta convertirse en una parte valiosa de los éxitos de su club, los Piratas, y una opción sólida para Hugo Broos con Sudáfrica. La carrera de Moremi realmente despegó con AmaZulu, donde fue ascendido desde las reservas por la leyenda sudafricana Benni McCarthy, quien entrenaba al club en ese momento. \"Benni McCarthy es la única leyenda a la que admiro\", dice. Sin embargo, su primer amor cuando era niño fue el sprint y, con sólo 11 años, rompió el récord de 100 metros de su escuela. El entrenador Motsamai Motsepe recordó el año pasado cómo tuvo que intervenir y reunirse con la madre de Moremi y el director de la escuela para convencerlos de que le dejaran jugar al fútbol también, después de haberlo visto dando por muertos a los defensores en un tiroteo local: \"Era crudo pero rápido como un rayo, y también zurdo\", dijo Motsepe a FarPost. \"Le dije a su madre que lo guiaría. Vi algo especial\".","en":"Fast and direct, Moremi’s nickname is “Rea Vaya”, colloquial Sesotho for “we are going”. His end product and overall consistency are still issues for the 25-year-old, but he has grown to become a valuable part of his club Pirates’ successes, and a solid option for Hugo Broos with South Africa. Moremi’s career really took off with AmaZulu where he was promoted from the reserves by South African legend Benni McCarthy, who was coaching the club at the time. “Benni McCarthy is the one legend I look up to,” he says. His first love as a boy, though, was sprinting, and, aged just 11, he broke his school’s 100m record. Coach Motsamai Motsepe recalled last year how he had to step in and meet Moremi’s mother and the school principal to convince them to let him play football too, having spotted him leaving defenders for dead in a local kickabout: “He was raw but lightning fast, and left-footed too,” Motsepe told FarPost. “I told his mother I’d guide him. I saw something special.”"}, special: "Former sprinter" },
  { number: 9, name: 'Lyle Foster', position: 'FW', age: 26, club: 'Burnley', bio: {"es":"El hombre en el que Sudáfrica confía para marcar goles, un auténtico punto focal del ataque. Durante la desafortunada campaña Afcon 2025 de los Bafana Bafana, donde el equipo quedó eliminado en octavos de final, Foster jugó cuatro veces, anotó dos veces y asistió dos veces, demostrando lo que la selección nacional se había perdido en 2023 cuando se perdió siete semanas de fútbol debido a problemas de salud mental. El año pasado habló sobre cómo lidiar con la ansiedad y la depresión, y agradeció a su club, Burnley, por su apoyo mientras se recuperaba: \"Todo el personal que estaba allí en ese momento y la gente dentro y alrededor del club, mi familia, los seguidores, realmente me hicieron sentir amado... Es muy importante tener gente a tu alrededor con la que puedas ser honesto y estoy agradecido de poder ser honesto con ellos. Estoy agradecido de que el club estuvo detrás de mí y de que pude tener ese pequeño descanso y volver al fútbol\". Será clave para la configuración ofensiva de Sudáfrica este verano. El joven de 25 años no es el único futbolista de su familia. Su primo Luther Singh, que juega en el club chipriota AEL Limassol, también jugó en los Bafana Bafana en el pasado.","en":"The man South Africa relies on for goals, a real focal point of the attack. During Bafana Bafana’s ill-fated 2025 Afcon campaign, where the team exited in the round of 16, Foster played four times, scoring twice and assisting twice – showing what the national side had missed in 2023 when he missed seven weeks of football due to mental health issues. He spoke last year about dealing with anxiety and depression, thanking his club, Burnley, for their support as he recovered: “All the staff that were there at the time and the people in and around the club, my family, the supporters, they really made me feel loved … It’s very important to have people around you who you can be honest with and I was grateful I could be honest with them. I’m grateful that the club stood behind me and that I was able to have that little break and come back to football.” He will be key to South Africa’s attacking set-up this summer. The 25-year-old is not the only footballer in his family. His cousin Luther Singh, who plays for Cypriot club AEL Limassol, has also played for Bafana Bafana in the past."}, special: "Goal threat" },
  { number: 10, name: 'Relebohile Mofokeng', position: 'FW', age: 21, club: 'Orlando Pirates', bio: {"es":"Uno de los talentos emergentes más interesantes del fútbol sudafricano. Producto de la Escuela de Excelencia Transnet, que formó jugadores como el excentrocampista del Everton Steven Pienaar, Mofokeng hizo su debut en el club absoluto en mayo de 2023. Desde entonces, el extremo se ha consolidado como un firme favorito de los fanáticos. “A veces el talento no alcanza para cubrir todo lo que requiere este juego”, afirmó el exentrenador de los Piratas José Riveiro. \"Rele también es un joven trabajador\". El entrenador de los Bafana Bafana, Hugo Broos, siente exactamente lo mismo por la joven estrella, pero tiene una visión diferente sobre su mejor posición. “Creo que lo fundamental es el futuro de Rele”, dijo en marzo. \"Puede jugar en banda contra un oponente que no es fuerte, pero contra oponentes fuertes no es un extremo. No tiene esa explosividad, el regate a un jugador por la línea. Su calidad es su inteligencia, dar buenos pases, usar los espacios, eso es lo que mejor hace Rele. Con los Bafana juega allí, no en la banda\". This summer gives Mofokeng the perfect platform to earn an overseas move.","en":"One of the most exciting emerging talents in South African football. A product of the Transnet School of Excellence, which produced players such as the former Everton midfielder Steven Pienaar, Mofokeng made his senior club debut in May 2023. Since then, the winger has established himself as a firm fan favourite. “Sometimes talent is not enough to cover everything that this game requires,” said the former Pirates coach José Riveiro. “Rele is a hard-working young man as well.” Bafana Bafana coach Hugo Broos feels exactly the same way about the young star – but has a different view on his best position. “I think central is the future for Rele,” he said in March. “He can play on the wing against an opponent that is not strong, but against strong opposition he is not a winger. He doesn’t have that explosiveness, the dribbling past a player down the line. His quality is his intelligence, giving good passes, using the spaces, that is what Rele is best at. With Bafana he plays there, not on the wing.” This summer gives Mofokeng the perfect platform to earn an overseas move."} },
  { number: 11, name: 'Themba Zwane', position: 'FW', age: 37, club: 'Mamelodi Sundowns', bio: {"es":"También conocido como Mshishi Uyashelela. La primera parte del apodo es el nombre del clan de Zwane, la segunda tiene que ver con el tipo de jugador que es en el campo de juego. En inglés simplemente significa que es fluido, lo que refleja sus habilidades, compostura y enorme inteligencia futbolística mientras se desliza por el medio campo. Es un pasador visionario, un gran regateador y un líder. Quienes conocen el fútbol sudafricano a menudo lo comparan, como personalidad, con N'Golo Kanté: una persona muy querida, de voz suave y un verdadero modelo a seguir para los jóvenes. Habiendo logrado evitar lesiones durante gran parte de su larga carrera, el veterano tuvo problemas en el período previo a este torneo, y Hugo Broos lo trató con precaución, limitando su tiempo de juego. \"Futbolísticamente sabemos que no hay problema\", dijo, \"pero físicamente... no creo que pueda jugar 90 minutos, pero verlo jugar es muy importante para nosotros. Creo que cuando esté con nosotros tenemos que dejarlo jugar\". Un Zwane en buena forma es una parte invaluable de este equipo.","en":"AKA Mshishi Uyashelela. The first part of the nickname is Zwane’s clan name, the second is all about the type of player he is on the field of play. In English it simply means he is smooth – reflecting his skills, composure and huge football intelligence as he glides through midfield. He is a visionary passer, great dribbler and a leader. Those around South African football often compare him, as a personality, to N'Golo Kanté – a much-loved, softly-spoken person, and real role model for youngsters. Having managed to avoid injuries for much of his long career, the veteran did struggle in the period before this tournament, and Hugo Broos treated him with caution, limiting his game-time. “Football-wise, we know there’s no problem,” he said, “but physically… I don’t think he can do 90 minutes, but just to see him play is very important for us. I think when he’s with us we have to let him play.” A properly fit Zwane is an invaluable part of this squad."}, special: "Veteran" },
  { number: 12, name: 'Thapelo Maseko', position: 'FW', age: 22, club: 'Mamelodi Sundowns', bio: {"es":"Maseko formó parte del equipo de Sudáfrica que consiguió el bronce en la Copa Africana de Naciones de 2023, pero su alegría duró poco: una lesión sufrida en el torneo estancó su carrera mientras luchaba por recuperar su condición física y su forma. Perdió su lugar en Mamelodi Sundowns y fue relegado a la reserva. Escribió en las redes sociales: \"Ni siquiera sé cuándo empezó, pero últimamente es como si el fuego en mí se estuviera apagando. Todavía entreno como si mi vida dependiera de ello. Pero por dentro me siento vacío\". En enero de 2026, el Limassol, con sede en Chipre, le ofreció una salida con un acuerdo de cesión, y cuando debutó con ellos en febrero, fue su primer inicio competitivo en casi dos años. Publicó: \"662 días sin empezar... aprendí a tener paciencia... aprendí la humildad... aprendí quién soy. Anoche significó más de lo que las palabras pueden explicar\". Hizo lo suficiente allí para ganarse un lugar en el equipo este verano y es una opción sólida para Hugo Broos, el tipo de jugador rápido y directo que quieres involucrar cuando dependes de los contraataques.","en":"Maseko was part of the South Africa team that secured bronze at the 2023 Africa Cup of Nations, but his joy was short-lived: an injury sustained at the tournament stalled his career as he struggled to regain fitness and form. He lost his place at Mamelodi Sundowns and was relegated to the reserves. He wrote on social media: \"I don’t even know when it started, but lately it’s like the fire in me is fading. I still train like my life depends on it. But inside it feels empty.” In January 2026 Cyprus-based club Limassol offered him a way out with a loan deal, and when he made his debut for them in February it was his first competitive start in nearly two years. He posted: “662 days without a start … I learned patience … I learned humility … I learned who I am. Last night meant more than words can explain.” He did enough there to earn his place in the squad this summer and is a solid option for Hugo Broos – the type of fast, direct player you want involved when you are relying on counters."} },
  { number: 15, name: 'Iqraam Rayners', position: 'FW', age: 30, club: 'Mamelodi Sundowns', bio: {"es":"El seleccionador de Sudáfrica, Hugo Broos, prefiere a los delanteros altos y físicos, lo que dificulta que Rayners, de 1,75 m, pueda jugar con su país con tanta regularidad como su forma en el club indica que debería hacerlo. Pero demostró que puede competir contra algunas de las mayores estrellas mundiales cuando anotó dos goles en tres apariciones en la primera Copa Mundial de Clubes de la FIFA ampliada. Opera como delantero para Sundowns, pero también ha pasado gran parte de su carrera jugando en la banda, lo que explica su habilidad instintiva para desplazarse hacia la izquierda o hacia la derecha y arrastrar a los defensores con él. El fútbol ha marcado una gran diferencia en la vida de su familia. \"Me crió mi abuela y nos mudábamos todo el tiempo\", dijo en 2020. \"Nos movíamos mucho, perdí la cuenta. Viajaba para entrenar, pero a veces no tenía dinero para llegar\". Pero eso cambió cuando su carrera despegó. \"Les compré una casa a mis padres. Ahora tienen un lugar al que llamar hogar\".","en":"The South Africa coach, Hugo Broos, favours tall and physical strikers, making it harder for the 1.75m Rayners to feature as regularly for his country as his club form indicates he should. But he showed he can compete against some of the biggest global stars when he scored two goals in three appearances at the inaugural expanded Fifa Club World Cup. He operates as a striker for Sundowns but has also spent large chunks of his career playing on the wing, explaining his instinctive ability to drift either left or right and pull defenders with him. Football has made a big difference to his family’s life. “I was raised by my grandmother and we kept on moving all the time,” he said in 2020. “We moved a lot, I lost count. I was travelling to training, but sometimes I didn’t have the money to get there.” But that changed as his career took off. “I bought my parents a house. Now they have a place to call their home.”"} },
  { number: 17, name: 'Evidence Makgopa', position: 'FW', age: 26, club: 'Orlando Pirates', bio: {"es":"Hoy en día, Makgopa es un delantero tradicional, pero no siempre fue así. En sus primeros años fue defensor, luego avanzó para convertirse en un mediocampista cuando inicialmente se unió a Baroka, el club donde obtuvo sus galones después de que lo exploraran del equipo de cuarta división Peace United en 2018. Permaneció en Baroka durante tres años, antes de hacer el cambio de vida a los Piratas en 2022, donde se ha convertido en una sólida presencia física de 1,88 m en la delantera, una verdadera amenaza en el aire, aunque no prolífica. Ha tenido altibajos con los aficionados a nivel internacional, pero se lo toma con calma y dijo en 2024: \"Creo que no puedes obligar a alguien a amarte y no puedes obligar a alguien a que te apoye. Para mí, creo que simplemente tengo que tomar las cosas como están y seguir adelante. Juego con todo mi corazón para el entrenador, porque él cree en mí. No hay nada que pueda sacudirme\".","en":"These days Makgopa is a traditional striker, but that wasn’t always the way. In his early years he was a defender, then moved forward to become a playmaking midfielder when he initially joined Baroka – the club where he earned his stripes after they scouted him from fourth-tier side Peace United in 2018. He remained with Baroka for three years, before making the life-changing switch to Pirates in 2022, where he has become a solid 1.88m physical presence up front, a real threat in the air, though not prolific. He has had ups and downs with fans at international level, but takes it in his stride, saying in 2024: “I think you cannot force someone to love you and you cannot force someone to support you. For me, I think I just have to take it the way it is and move forward. I play wholeheartedly for the coach, because he believes in me. There's nothing that can shake me.''"} },
];

